1	//! Recording save + transcription queue, mirroring the desktop
2	//! `commands/recordings.rs` surface. Native capture and local Whisper stay in
3	//! their shells — a React Native host records via its own audio module and
4	//! calls `save_audio_recording`, then either queues AssemblyAI, queues its own
5	//! [`TranscriptionProvider`], or leaves recordings `pending` for a desktop to
6	//! transcribe after git sync (`transcription_mode: "desktop"`).
7	
8	use std::sync::Arc;
9	
10	use type_core::{
11	    application::recordings::RecordingsUseCases, queue_recordings_for_provider_transcription,
12	    QueueRecordingsArgs, ReadRecordingAudioArgs, RecordingsAdapter, SaveRecordingArgs,
13	};
14	
15	use crate::{from_json, run_blocking, to_json, unlocked_env, CoreError};
16	
17	fn recordings_use_cases() -> Result<RecordingsUseCases<RecordingsAdapter>, String> {
18	    Ok(RecordingsUseCases::new(RecordingsAdapter::new(
19	        unlocked_env()?,
20	    )))
21	}
22	
23	/// A transcription backend implemented by the host (Swift/Kotlin/JS) — e.g.
24	/// native on-device speech recognition. Methods are called from the queue's
25	/// Rust worker thread, one job at a time.
26	#[uniffi::export(with_foreign)]
27	pub trait TranscriptionProvider: Send + Sync {
28	    /// Stable identifier used in error messages, e.g. "apple-speech".
29	    fn id(&self) -> String;
30	    /// Transcribe the audio file at `audio_path` (absolute) and return the
31	    /// transcript text.
32	    fn transcribe(&self, audio_path: String) -> Result<String, CoreError>;
33	}
34	
35	/// Bridges the FFI trait onto the core port so queued jobs can call back into
36	/// the host implementation.
37	struct ForeignTranscriptionProvider(Arc<dyn TranscriptionProvider>);
38	
39	impl type_core::ports::recordings::TranscriptionProvider for ForeignTranscriptionProvider {
40	    fn id(&self) -> String {
41	        self.0.id()
42	    }
43	
44	    fn transcribe(&self, audio_path: &std::path::Path) -> Result<String, String> {
45	        self.0
46	            .transcribe(audio_path.to_string_lossy().into_owned())
47	            .map_err(|error| error.to_string())
48	    }
49	}
50	
51	/// `args_json`: `SaveRecordingArgs` (`audio_base64`, optional `mime_type` /
52	/// `folder_path` / `file_name_format`). Returns JSON `RecordingWriteResult`.
53	/// The new note starts with `transcription_status: pending`.
54	#[uniffi::export(async_runtime = "tokio")]
55	pub async fn save_audio_recording(args_json: String) -> Result<String, CoreError> {
56	    run_blocking(move || {
57	        let args: SaveRecordingArgs = from_json(&args_json)?;
58	        to_json(&recordings_use_cases()?.save(args)?)
59	    })
60	    .await
61	}
62	
63	/// Queue every pending/failed recording for AssemblyAI. `args_json`:
64	/// `QueueRecordingsArgs` (optional `assembly_api_key`, falling back to the
65	/// device app config). Returns JSON `RecordingTranscriptionQueueResult`.
66	#[uniffi::export(async_runtime = "tokio")]
67	pub async fn queue_recording_transcriptions(args_json: String) -> Result<String, CoreError> {
68	    run_blocking(move || {
69	        let args: QueueRecordingsArgs = from_json(&args_json)?;
70	        to_json(&recordings_use_cases()?.queue_cloud(args)?)
71	    })
72	    .await
73	}
74	
75	/// Queue every pending/failed recording against a host-supplied
76	/// [`TranscriptionProvider`]. Returns JSON `RecordingTranscriptionQueueResult`;
77	/// jobs then run on the shared background worker.
78	#[uniffi::export(async_runtime = "tokio")]
79	pub async fn queue_provider_transcriptions(
80	    provider: Arc<dyn TranscriptionProvider>,
81	) -> Result<String, CoreError> {
82	    run_blocking(move || {
83	        let root = type_core::ensured_notes_root(&unlocked_env()?)?;
84	        let bridged: Arc<dyn type_core::ports::recordings::TranscriptionProvider> =
85	            Arc::new(ForeignTranscriptionProvider(provider));
86	        to_json(&queue_recordings_for_provider_transcription(&root, bridged)?)
87	    })
88	    .await
89	}
90	
91	/// Queue snapshot + all recording notes as JSON (`RecordingsListResult`).
92	#[uniffi::export(async_runtime = "tokio")]
93	pub async fn list_recordings() -> Result<String, CoreError> {
94	    run_blocking(|| to_json(&recordings_use_cases()?.list()?)).await
95	}
96	
97	/// Audio bytes for a recording as JSON (`RecordingAudioPayload`), path must be
98	/// inside the `Recordings/` storage folder.
99	#[uniffi::export(async_runtime = "tokio")]
100	pub async fn read_recording_audio(path: String) -> Result<String, CoreError> {
